/**
 * Hephaestus API types, generated from ../contracts/hephaestus.openapi.yaml.
 * Regenerate with `pnpm generate:api`; never edit ./generated by hand.
 */
export type ApiSchemas = components["schemas"];
export type ApiSchema<K extends keyof ApiSchemas> = ApiSchemas[K];
